/**
 * Kumva SendMessage Node
 * Sends SMS or IVR messages using Africa's Talking SDK
 */

module.exports = function(RED) {
  const AfricasTalkingService = require('kumva-insights/utils/africastalking');
  const ConfigManager = require('kumva-insights/utils/config-manager');
  const helpers = require('kumva-insights/utils/helpers');

  // Shared service instance
  let africasTalkingService = null;
  let configManager = null;

  /**
   * Initialize Africa's Talking service
   */
  function initializeService() {
    if (!africasTalkingService) {
      configManager = new ConfigManager();
      const credentials = configManager.getAfricasTalkingConfig();

      if (!credentials.apiKey || !credentials.username) {
        throw new Error('Africa\'s Talking credentials not configured. Please configure in global settings.');
      }

      africasTalkingService = new AfricasTalkingService(credentials);
    }

    return africasTalkingService;
  }

  function KumvaSendMessageNode(config) {
    RED.nodes.createNode(this, config);
    const node = this;

    // Track retry attempts
    const retryTracker = {};

    /**
     * Get phone number from various sources
     */
    function getPhoneNumber(msg) {
      const source = config.phoneSource || 'msg';

      switch(source) {
        case 'static':
          return config.staticPhone;

        case 'variable':
          const varName = config.variablePhone || 'phoneNumber';
          return msg[varName];

        case 'msg':
        default:
          return msg.phoneNumber;
      }
    }

    /**
     * Get message content
     */
    function getMessageContent(msg) {
      const messageType = config.messageType || 'sms';

      let content;
      switch(messageType) {
        case 'sms':
          content = config.messageContent || msg.initialMessage || '';
          break;
        case 'ivr-audio':
          content = config.audioUrl || msg.initialMessage || '';
          break;
        case 'ivr-tts':
          content = config.ttsText || msg.initialMessage || '';
          break;
        default:
          content = '';
      }

      // Resolve variables in content
      return helpers.resolveVariables(content, msg);
    }

    /**
     * Send SMS message
     */
    async function sendSMS(phoneNumber, message, msg) {
      try {
        const service = initializeService();
        const shortCode = msg.shortCode || configManager.get('defaults.shortCode', null);

        const result = await service.sendSMS(phoneNumber, message, shortCode);

        if (result.success) {
          node.log(`SMS sent to ${phoneNumber} - ID: ${result.messageId}`);
          return {
            success: true,
            messageId: result.messageId,
            fullResult: result.data
          };
        } else {
          throw new Error(result.error || 'Failed to send SMS');
        }
      } catch (error) {
        node.error(`SMS send error: ${error.message}`);
        return {
          success: false,
          error: error.message
        };
      }
    }

    /**
     * Send IVR message
     */
    async function sendIVR(phoneNumber, ivrConfig, msg) {
      try {
        const service = initializeService();
        const callerId = msg.shortCode || configManager.get('defaults.callerId', null);

        const ivrOptions = {
          callerId: callerId,
          ...ivrConfig
        };

        const result = await service.sendIVR(phoneNumber, ivrOptions);

        if (result.success) {
          node.log(`IVR sent to ${phoneNumber} - Session: ${result.sessionId}`);
          return {
            success: true,
            sessionId: result.sessionId,
            fullResult: result.data
          };
        } else {
          throw new Error(result.error || 'Failed to send IVR');
        }
      } catch (error) {
        node.error(`IVR send error: ${error.message}`);
        return {
          success: false,
          error: error.message
        };
      }
    }

    /**
     * Handle message sending with retry logic
     */
    async function handleSendMessage(msg, sendFn) {
      const retryKey = msg.sessionId || `${msg.phoneNumber}_${Date.now()}`;
      const currentAttempt = (retryTracker[retryKey] || 0) + 1;
      retryTracker[retryKey] = currentAttempt;

      try {
        const result = await sendFn();

        if (result.success) {
          // Clear retry counter
          delete retryTracker[retryKey];
          return result;
        } else {
          // Check if should retry
          const maxRetries = config.maxRetries || 3;
          if (config.retryOnFailure && currentAttempt < maxRetries) {
            node.warn(`Send failed, retrying (${currentAttempt}/${maxRetries})`);
            // Retry after delay
            await helpers.delay(1000 * currentAttempt); // Exponential backoff
            return handleSendMessage(msg, sendFn);
          } else {
            throw new Error(result.error || 'Failed to send message');
          }
        }
      } catch (error) {
        delete retryTracker[retryKey];
        throw error;
      }
    }

    /**
     * Handle incoming messages
     */
    node.on('input', async function(msg) {
      try {
        // Validate required fields
        const phoneNumber = getPhoneNumber(msg);
        if (!phoneNumber) {
          node.error('Phone number not found in message');
          node.status({
            fill: 'red',
            shape: 'ring',
            text: 'No phone number'
          });
          return;
        }

        if (!helpers.isValidPhoneNumber(phoneNumber)) {
          node.error(`Invalid phone number: ${phoneNumber}`);
          node.status({
            fill: 'red',
            shape: 'ring',
            text: 'Invalid phone'
          });
          return;
        }

        // Update status
        node.status({
          fill: 'blue',
          shape: 'dot',
          text: 'Sending...'
        });

        const messageType = config.messageType || 'sms';
        let result;

        if (messageType === 'sms') {
          // Handle SMS
          const content = getMessageContent(msg);
          if (!content) {
            throw new Error('No message content provided');
          }

          result = await handleSendMessage(msg, () => 
            sendSMS(phoneNumber, content, msg)
          );

        } else if (messageType === 'ivr-audio') {
          // Handle IVR with audio
          const audioUrl = getMessageContent(msg);
          if (!audioUrl) {
            throw new Error('No audio URL provided');
          }

          result = await handleSendMessage(msg, () =>
            sendIVR(phoneNumber, { audioUrl }, msg)
          );

        } else if (messageType === 'ivr-tts') {
          // Handle IVR with TTS
          const ttsText = getMessageContent(msg);
          if (!ttsText) {
            throw new Error('No TTS text provided');
          }

          result = await handleSendMessage(msg, () =>
            sendIVR(phoneNumber, { ttsText }, msg)
          );
        }

        if (!result.success) {
          throw new Error(result.error);
        }

        // Debug logging
        if (config.debugMode) {
          node.log(`Message sent successfully`);
          node.log(`To: ${phoneNumber}`);
          node.log(`Type: ${messageType}`);
        }

        // Prepare output message
        const outputMsg = {
          ...msg,
          messageId: result.messageId || null,
          sessionId: result.sessionId || msg.sessionId,
          sendStatus: 'success',
          sendResult: result.fullResult,
          _kumva: {
            ...msg._kumva,
            lastMessageId: result.messageId,
            sentAt: new Date().toISOString()
          }
        };

        node.status({
          fill: 'green',
          shape: 'dot',
          text: 'Sent'
        });

        node.send(outputMsg);

      } catch (error) {
        node.error(`SendMessage error: ${error.message}`);
        node.status({
          fill: 'red',
          shape: 'ring',
          text: 'Error sending'
        });

        // Send error message
        msg.sendStatus = 'failed';
        msg.sendError = error.message;
        node.send(msg);
      }
    });

    /**
     * Cleanup on close
     */
    node.on('close', function(done) {
      // Clear retry tracker for this node
      Object.keys(retryTracker).forEach(key => delete retryTracker[key]);
      done();
    });

    // Initialize status
    node.status({
      fill: 'yellow',
      shape: 'ring',
      text: 'Ready'
    });
  }

  RED.nodes.registerType('kumva-send-message', KumvaSendMessageNode);
};